mapper.sql:
SELECT e.id, e.platform_id, e.create_time, e.room_id, e.status AS mapped_status FROM external_order e WHERE 1=1 AND e.platform_id = #{platform} AND e.anchor_id = #{anchor} AND e.room_id = #{room} AND e.check_in_date < #{end} AND e.check_out_date > #{start} AND e.status = #{status}
AND (e.order_no LIKE CONCAT('%', #{keyword}, '%') OR e.platform_order_no LIKE CONCAT('%', #{keyword}, '%'))
UNION ALL SELECT m.id, #{miniSource} AS platform_id, m.create_time, COALESCE(m.room_id, unique_room.room_id) AS room_id, CASE WHEN m.status = 'cancelled' THEN 'CANCELLED' WHEN m.status = 'checked_in' THEN 'CHECKED_IN' WHEN m.status = 'checked_out' THEN 'CHECKED_OUT' WHEN m.total_price > 0 AND m.paid_amount >= m.total_price THEN 'BOOKED' ELSE 'AWAITING_PAYMENT' END AS mapped_status FROM booking_order m LEFT JOIN (SELECT room_type_id, MIN(id) AS room_id FROM room WHERE deleted=0 GROUP BY room_type_id HAVING COUNT(*)=1) unique_room ON unique_room.room_type_id=m.room_type_id WHERE m.deleted=0 AND m.status IN ('awaiting_payment','pending','confirmed','checked_in','checked_out','cancelled') AND 1=0 AND 1=0 AND COALESCE(m.room_id, unique_room.room_id) = #{room} AND m.check_in_date < #{end} AND m.check_out_date > #{start} AND LOCATE(LOWER(TRIM(#{keyword})), LOWER(m.order_no)) > 0
